from pyparsing import ParseException
from threading import Lock
from ute_admin_infomodel.exception import InfoModelExpressionSyntaxException

parser_lock = Lock()


class InfoModelParser(object):

    def parse(self, expression):
        """Parse expression."""
        try:
            with parser_lock:
                return self.grammar.parseString(expression)
        except ParseException as e:
            raise InfoModelExpressionSyntaxException("%s in expression: '%s'" % (str(e), expression))
